code-is_palindrome:
def is_palindrome(s):
    t=[c.lower() for c in s if c.isalnum()]
    return t==t[::-1]

code-word_freq:
def word_freq(text):
    d={}
    for w in text.split():
        w=w.strip('.,!?').lower()
        if w: d[w]=d.get(w,0)+1
    return d

code-compress:
def compress(s):
    out=[];i=0
    while i<len(s):
        j=i
        while j<len(s) and s[j]==s[i]: j+=1
        out.append(f"{s[i]}{j-i}"); i=j
    return ''.join(out)

code-is_anagram:
def is_anagram(a,b):
    f=lambda s: sorted(s.replace(' ','').lower())
    return f(a)==f(b)

code-second_largest:
def second_largest(nums):
    u=sorted(set(nums))
    return u[-2] if len(u)>1 else None

code-flatten:
def flatten(x):
    out=[]
    for v in x:
        out.extend(flatten(v) if isinstance(v,list) else [v])
    return out

code-merge_intervals:
def merge_intervals(iv):
    out=[]
    for s,e in sorted(iv):
        if out and s<=out[-1][1]: out[-1][1]=max(out[-1][1],e)
        else: out.append([s,e])
    return out

code-digit_sum:
def digital_root(n):
    while n>9: n=sum(map(int,str(n)))
    return n

code-valid_brackets:
def valid_brackets(s):
    st=[];pairs={')':'(',']':'[','}':'{'}
    for c in s:
        if c in '([{': st.append(c)
        elif c in pairs:
            if not st or st.pop()!=pairs[c]: return False
    return not st

code-two_sum:
def two_sum(nums,target):
    seen={}
    for j,v in enumerate(nums):
        if target-v in seen: return (seen[target-v],j)
        seen.setdefault(v,j)
    return None
